//
// generate.mjs — the generator half of devtools/vendor-aws-sdk-js (P9,
// D-P9-02-5 / D-P9-02-8 / D-P9-02-9). Run from a directory where `npm ci` has
// installed this package's pinned dependencies and esbuild has written
// `meta.json` (its --metafile output). It writes, into <outdir>:
//
//   allowed-hosts.mjs         REGIONS, ALLOWED_HOSTS, SDK_VERSION — the single
//                             source for the browser edition's endpoint
//                             allowlist and its CSP connect-src list.
//   THIRD-PARTY-NOTICES.txt   every package bundled into aws-sdk-dynamodb.mjs,
//                             its version and license, followed by the distinct
//                             license texts.
//
// and, when <index.html> is given, rewrites the CSP <meta> between the
// `csp:begin` / `csp:end` markers so connect-src lists exactly
// 'self' + every ALLOWED_HOSTS entry.
//
// Usage: node generate.mjs <outdir> [<index.html>]

import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const [outdir, indexHtml] = process.argv.slice(2);
if (!outdir) {
    console.error("usage: node generate.mjs <outdir> [<index.html>]");
    process.exit(2);
}

// ---- regions + hosts (D-P9-02-5) -------------------------------------------
// The pinned SDK's partition table is the source of truth for region names and
// DNS suffixes. Only the `aws` and `aws-us-gov` partitions are in scope; their
// pseudo-regions (`aws-global`, `aws-us-gov-global`) are not real endpoints.
const partitionsPath = "node_modules/@aws-sdk/core/dist-es/submodules/client/util-endpoints/lib/aws/partitions.js";
const { partitionsInfo } = await import(join(process.cwd(), partitionsPath));
const IN_SCOPE = new Set(["aws", "aws-us-gov"]);
const regions = [];
const hosts = [];
for (const p of partitionsInfo.partitions) {
    if (!IN_SCOPE.has(p.id)) {
        continue;
    }
    const suffixes = [p.outputs.dnsSuffix, p.outputs.dualStackDnsSuffix];
    for (const r of Object.keys(p.regions).sort()) {
        if (r.startsWith("aws-")) {
            continue;
        }
        regions.push(r);
        // `search-dynamodb[-fips]` is where the SDK's endpoint rules route
        // SearchVectors (vector search); the other operations use `dynamodb[-fips]`.
        for (const label of ["dynamodb", "dynamodb-fips", "search-dynamodb", "search-dynamodb-fips"]) {
            for (const suffix of suffixes) {
                hosts.push(`${label}.${r}.${suffix}`);
            }
        }
    }
}
regions.sort();
hosts.sort();

const sdkVersion = JSON.parse(
    readFileSync("node_modules/@aws-sdk/client-dynamodb/package.json", "utf8")).version;

const allowed = [
    "// Copyright 2026 ddbsh reimplementation contributors.",
    "// SPDX-License-Identifier: Apache-2.0",
    "//",
    "// allowed-hosts.mjs — GENERATED by devtools/vendor-aws-sdk-js from the pinned",
    "// @aws-sdk/client-dynamodb partition data. Do not edit by hand.",
    "//",
    "// REGIONS: every region of the `aws` and `aws-us-gov` partitions.",
    "// ALLOWED_HOSTS: [search-]dynamodb[-fips].<region>.{amazonaws.com,api.aws} for",
    "// each (the SDK routes SearchVectors to the search-dynamodb hosts).",
    "// SDK_VERSION: the bundled @aws-sdk/client-dynamodb version (SHOW CONNECTION).",
    "// The browser edition refuses every other DynamoDB endpoint (D-P9-02-5), and",
    "// index.html's CSP connect-src lists exactly these hosts (D-P9-02-9).",
    "",
    `export const SDK_VERSION = ${JSON.stringify(sdkVersion)};`,
    "",
    `export const REGIONS = Object.freeze(${JSON.stringify(regions, null, 4)});`,
    "",
    `export const ALLOWED_HOSTS = Object.freeze(${JSON.stringify(hosts, null, 4)});`,
    "",
].join("\n");
writeFileSync(join(outdir, "allowed-hosts.mjs"), allowed);

// ---- third-party notices ---------------------------------------------------
const meta = JSON.parse(readFileSync("meta.json", "utf8"));
const pkgs = new Map(); // "name" -> dir
for (const input of Object.keys(meta.inputs)) {
    const m = input.match(/^(?:.*\/)?node_modules\/((?:@[^/]+\/)?[^/]+)\//);
    if (m) {
        const dir = input.slice(0, input.indexOf(m[1]) + m[1].length);
        pkgs.set(m[1], dir);
    }
}
const names = [...pkgs.keys()].sort();
const lines = [
    "Third-party software bundled into aws-sdk-dynamodb.mjs",
    "(generated by devtools/vendor-aws-sdk-js from esbuild's --metafile input list)",
    "",
];
const texts = new Map(); // sha256 -> {text, packages[]}
for (const name of names) {
    const dir = pkgs.get(name);
    const pj = JSON.parse(readFileSync(join(dir, "package.json"), "utf8"));
    const license = typeof pj.license === "string" ? pj.license : JSON.stringify(pj.license ?? "UNKNOWN");
    lines.push(`${name}@${pj.version}  ${license}`);
    for (const f of ["LICENSE", "LICENSE.txt", "LICENSE.md", "license", "NOTICE", "NOTICE.txt"]) {
        const p = join(dir, f);
        if (existsSync(p)) {
            const text = readFileSync(p, "utf8").trim();
            const h = createHash("sha256").update(text).digest("hex");
            if (!texts.has(h)) {
                texts.set(h, { text, packages: [] });
            }
            texts.get(h).packages.push(`${name} (${f})`);
        }
    }
}
lines.push("");
for (const { text, packages } of texts.values()) {
    lines.push("=".repeat(78));
    lines.push(`Applies to: ${packages.join(", ")}`);
    lines.push("=".repeat(78));
    lines.push(text);
    lines.push("");
}
writeFileSync(join(outdir, "THIRD-PARTY-NOTICES.txt"), lines.join("\n"));

// ---- CSP connect-src in index.html (D-P9-02-9) -----------------------------
if (indexHtml) {
    const html = readFileSync(indexHtml, "utf8");
    const re = /(<!-- csp:begin -->)[\s\S]*?(<!-- csp:end -->)/;
    if (!re.test(html)) {
        console.error(`generate.mjs: no csp:begin/csp:end markers in ${indexHtml}`);
        process.exit(1);
    }
    const connect = ["'self'", ...hosts.map((h) => `https://${h}`)].join(" ");
    const csp = [
        "default-src 'none'",
        "script-src 'self' 'wasm-unsafe-eval'",
        `connect-src ${connect}`,
        "style-src 'self'",
        "img-src 'self'",
        "base-uri 'none'",
        "form-action 'none'",
        "object-src 'none'",
        // Trusted Types (P10, D-P10-12): no string reaches a DOM injection sink
        // (innerHTML, a script URL, eval-like calls) and no Trusted Types
        // policy may be created. The page writes text with textContent only.
        "require-trusted-types-for 'script'",
        "trusted-types 'none'",
    ].join("; ");
    const meta = `<meta http-equiv="Content-Security-Policy" content="${csp}">`;
    writeFileSync(indexHtml, html.replace(re, `$1\n    ${meta}\n    $2`));
}
